// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro, QuestaoDaAvaliacao } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"O que é uma escola bem organizada","html":"<p>Uma escola bem organizada é aquela em que o aluno está presente, aprende e é protegido, e em que a equipe sabe o que fazer, tem o que precisa e é ouvida.</p><p>Este guia reúne as rotinas de gestão que sustentam esse resultado e mostra como a Secretaria pode acompanhar e apoiar cada escola.</p><h3>Ao final, você será capaz de</h3><ul><li>Reconhecer as quatro dimensões da gestão escolar.</li><li>Apoiar as escolas no planejamento do ano.</li><li>Organizar as rotinas que não podem falhar.</li><li>Acompanhar frequência, aprendizagem e clima com poucos indicadores.</li><li>Conduzir visitas de acompanhamento que ajudam a escola.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Dimensão</th><th>Pergunta central</th><th>Exemplos</th></tr></thead><tbody><tr><td>Pedagógica</td><td>Os alunos estão aprendendo?</td><td>Projeto pedagógico, planejamento, reuniões, reforço, avaliação.</td></tr><tr><td>De pessoas</td><td>A equipe está completa, formada e cuidada?</td><td>Lotação, formação, clima, substituições.</td></tr><tr><td>Administrativa</td><td>A escola tem o que precisa para funcionar?</td><td>Matrícula, merenda, transporte, prédio, recursos.</td></tr><tr><td>De convivência e proteção</td><td>A escola é um lugar seguro e democrático?</td><td>Regimento, conselho escolar, famílias, rede de proteção.</td></tr></tbody></table></div><div class=\"nota\"><b>Base legal</b><br/>A Constituição Federal (art. 206, VI) e a Lei de Diretrizes e Bases (art. 14) estabelecem a gestão democrática do ensino público, com participação dos profissionais no projeto pedagógico e da comunidade em conselhos escolares.</div>"},{"id":"c2","titulo":"Os documentos que organizam a escola","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Documento</th><th>Para que serve</th><th>Quem elabora</th><th>Quando rever</th></tr></thead><tbody><tr><td>Projeto político-pedagógico</td><td>Define a identidade, os objetivos e as prioridades da escola.</td><td>Equipe da escola, com a comunidade</td><td>Todo ano</td></tr><tr><td>Regimento escolar</td><td>Define as regras de funcionamento, os direitos e os deveres.</td><td>Escola, conforme as normas da rede</td><td>Quando as normas mudam</td></tr><tr><td>Plano de ação anual</td><td>Traduz as prioridades em metas, ações, prazos e responsáveis.</td><td>Direção e coordenação</td><td>A cada bimestre</td></tr><tr><td>Calendário escolar</td><td>Organiza os dias letivos, as reuniões e os eventos.</td><td>Secretaria e escola</td><td>Todo ano</td></tr><tr><td>Plano de segurança e proteção</td><td>Define como a escola age em emergências e em casos de violência.</td><td>Direção, com a Secretaria</td><td>Todo ano e após cada ocorrência</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Documento de gaveta</b><br/>Projeto pedagógico e plano de ação só valem se forem consultados. Um plano de uma página, com poucas metas e revisão bimestral, funciona melhor do que um documento longo.</div>"},{"id":"c3","titulo":"O ciclo do ano letivo","html":"<figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Preparar</b><small>matrícula, lotação, calendário</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Diagnosticar</b><small>onde os alunos estão</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Planejar</b><small>metas e plano de ação</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Executar e acompanhar</b><small>rotina, reuniões e apoio</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Avaliar</b><small>resultados e ajustes</small></div></div><figcaption>Figura. As etapas do ano letivo.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Período</th><th>Na escola</th><th>Na Secretaria</th></tr></thead><tbody><tr><td>Antes do início</td><td>Matrícula, enturmação, atribuição de aulas, preparação do prédio.</td><td>Lotação, calendário, transporte, merenda, cadastros nos sistemas.</td></tr><tr><td>Primeiro mês</td><td>Acolhimento, diagnóstico, reunião com responsáveis, plano de ação.</td><td>Formação inicial, conferência dos cadastros, apoio às escolas novas.</td></tr><tr><td>Durante o ano</td><td>Reuniões pedagógicas, conselho de classe, busca ativa, reforço.</td><td>Visitas, formação, acompanhamento de indicadores.</td></tr><tr><td>Fim de cada bimestre</td><td>Conselho de classe e revisão do plano.</td><td>Leitura dos resultados da rede e apoio dirigido.</td></tr><tr><td>Fim do ano</td><td>Avaliação do ano, rematrícula, registros finais.</td><td>Balanço da rede e planejamento do ano seguinte.</td></tr></tbody></table></div>"},{"id":"c4","titulo":"Rotinas que não podem falhar","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Rotina</th><th>O que garantir</th><th>Frequência</th></tr></thead><tbody><tr><td>Frequência dos alunos</td><td>Chamada feita e lançada. Contato com a família na terceira falta seguida.</td><td>Diária</td></tr><tr><td>Busca ativa</td><td>Localizar e trazer de volta o aluno que deixou de vir.</td><td>Semanal</td></tr><tr><td>Alimentação escolar</td><td>Cardápio cumprido, estoque conferido, higiene.</td><td>Diária</td></tr><tr><td>Transporte escolar</td><td>Rotas, horários e segurança dos alunos.</td><td>Diária</td></tr><tr><td>Substituição de professores</td><td>Nenhuma turma sem aula.</td><td>Diária</td></tr><tr><td>Manutenção e limpeza</td><td>Banheiros, água, iluminação, portões.</td><td>Diária e semanal</td></tr><tr><td>Cadastros e sistemas</td><td>Matrículas, turmas, atribuições e Censo Escolar atualizados.</td><td>Mensal</td></tr><tr><td>Prestação de contas</td><td>Recursos recebidos aplicados e registrados.</td><td>Conforme o programa</td></tr><tr><td>Comunicação com responsáveis</td><td>Avisos, reuniões e atendimento.</td><td>Semanal</td></tr></tbody></table></div><div class=\"nota\"><b>Faltas e Conselho Tutelar</b><br/>A Lei de Diretrizes e Bases (art. 12, VIII) determina que a escola notifique ao Conselho Tutelar a relação dos alunos com faltas acima de 30% do percentual permitido em lei.</div>"},{"id":"c5","titulo":"Gestão de pessoas","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Boas práticas</th></tr></thead><tbody><tr><td>Chegada de novos servidores</td><td>Receber, apresentar a escola, entregar as regras e os guias de formação, indicar um colega de referência.</td></tr><tr><td>Papéis claros</td><td>Cada função sabe o que é seu: direção, coordenação, secretaria escolar, professores, apoio.</td></tr><tr><td>Reuniões</td><td>Com pauta, tempo e registro. Avisos por escrito.</td></tr><tr><td>Retorno sobre o trabalho</td><td>Conversas individuais, com fatos e com respeito.</td></tr><tr><td>Conflitos</td><td>Tratados cedo, em conversa reservada, antes de virarem problema da equipe.</td></tr><tr><td>Cuidado</td><td>Atenção a sinais de esgotamento e encaminhamento ao serviço de saúde do servidor.</td></tr></tbody></table></div><h3>Quem faz o quê na escola</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Função</th><th>Responsabilidade principal</th></tr></thead><tbody><tr><td>Direção</td><td>Responde pela escola. Cuida de pessoas, recursos, convivência e relação com a Secretaria e a comunidade.</td></tr><tr><td>Coordenação pedagógica</td><td>Cuida do ensino: planejamento, formação dos professores, acompanhamento da aprendizagem.</td></tr><tr><td>Secretaria escolar</td><td>Cuida da vida escolar dos alunos: matrícula, documentos, frequência, cadastros.</td></tr><tr><td>Professores</td><td>Ensinam, avaliam, acompanham os alunos e participam do projeto pedagógico.</td></tr><tr><td>Equipe de apoio</td><td>Alimentação, limpeza, portaria e cuidado. São educadores no convívio diário com os alunos.</td></tr><tr><td>Conselho escolar</td><td>Reúne equipe, responsáveis e comunidade para acompanhar e decidir junto.</td></tr></tbody></table></div>"},{"id":"c6","titulo":"Poucos indicadores, bem acompanhados","html":"<p>Acompanhar muitos números dispersa. Cinco indicadores, vistos todo mês, dizem o essencial sobre uma escola.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Indicador</th><th>O que mostra</th><th>Fonte</th></tr></thead><tbody><tr><td>Frequência dos alunos</td><td>Se os alunos estão vindo.</td><td>Diário de classe</td></tr><tr><td>Alunos que praticam o reforço</td><td>Se o reforço chega a todos.</td><td>Plataforma de reforço</td></tr><tr><td>Habilidades recuperadas</td><td>Se os alunos estão avançando.</td><td>Plataforma de reforço</td></tr><tr><td>Responsáveis com acesso</td><td>Se as famílias acompanham.</td><td>Plataforma de reforço</td></tr><tr><td>Aulas dadas</td><td>Se as turmas têm professor.</td><td>Registro da escola</td></tr></tbody></table></div><figure><div class=\"colunas\"><div class=\"plot\"><div class=\"grp\"><div class=\"cols\"><span style=\"height:94%;background:#14467A\"><i>94</i></span><span style=\"height:78%;background:#1E8E5A\"><i>78</i></span></div><small>Escola 1</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:91%;background:#14467A\"><i>91</i></span><span style=\"height:71%;background:#1E8E5A\"><i>71</i></span></div><small>Escola 2</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:88%;background:#14467A\"><i>88</i></span><span style=\"height:66%;background:#1E8E5A\"><i>66</i></span></div><small>Escola 3</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:79%;background:#14467A\"><i>79</i></span><span style=\"height:41%;background:#1E8E5A\"><i>41</i></span></div><small>Escola 4</small></div><div class=\"grp\"><div class=\"cols\"><span style=\"height:72%;background:#14467A\"><i>72</i></span><span style=\"height:28.999999999999996%;background:#1E8E5A\"><i>29</i></span></div><small>Escola 5</small></div></div><div class=\"leg\"><span><i style=\"background:#14467A\"></i>Frequência dos alunos (%)</span><span><i style=\"background:#1E8E5A\"></i>Alunos que praticam o reforço (%)</span></div></div><figcaption>Gráfico (exemplo fictício). Frequência e prática do reforço por escola. As Escolas 4 e 5 pedem apoio.</figcaption></figure><div class=\"nota\"><b>Indicador serve para apoiar</b><br/>Os números orientam onde a Secretaria deve estar mais presente. Não servem para ranking nem para punir escolas.</div>"},{"id":"c7","titulo":"A visita de acompanhamento","html":"<p>A visita da Secretaria ajuda quando a escola sente que recebeu apoio, e não uma inspeção.</p><ol class=\"passos\"><li>Antes: ler os indicadores da escola e o plano de ação.</li><li>Chegada: conversar com a direção sobre o que vai bem e o que preocupa.</li><li>Circular: observar entrada, recreio, salas, cozinha e banheiros.</li><li>Ouvir: conversar com professores, equipe de apoio e alunos.</li><li>Fechar: combinar com a direção até três ações, com prazo e com o apoio que a Secretaria dará.</li><li>Depois: cumprir o que a Secretaria prometeu e voltar na data combinada.</li></ol><figure><div class=\"matriz\"><div class=\"ey\">Organização</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Organizada, resultados baixos</b><small>Apoio pedagógico: formação, reuniões com dados, reforço.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Organizada, bons resultados</b><small>Reconhecer e usar como referência para outras escolas.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Desorganizada, resultados baixos</b><small>Presença intensiva: rotinas básicas primeiro.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Desorganizada, bons resultados</b><small>Resultado depende de pessoas. Fortalecer as rotinas para sustentar.</small></div></div><div class=\"ex\">Resultados</div></div><figcaption>Figura. Como definir o tipo de apoio a cada escola.</figcaption></figure>"},{"id":"c8","titulo":"Família, comunidade e conselho escolar","html":"<ul><li>Reunir os responsáveis no início do ano para apresentar a equipe, as regras e o reforço escolar.</li><li>Manter um canal simples de comunicação e responder em prazo conhecido.</li><li>Convidar os responsáveis a acompanhar a evolução do aluno pela plataforma.</li><li>Manter o conselho escolar ativo, com reuniões regulares e pauta real.</li><li>Conhecer os serviços do território: saúde, assistência social, Conselho Tutelar.</li><li>Abrir a escola à comunidade em atividades planejadas.</li></ul><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a escola com muitas faltas</div><p><b>Situação.</b> Uma escola tem frequência de 72%, a mais baixa da rede.</p><p><b>O que fazer.</b></p><ol><li>Na visita, veja com a direção em quais turmas e dias as faltas se concentram.</li><li>Verifique transporte, merenda e segurança no trajeto.</li><li>Apoie a escola a organizar a busca ativa, com contato na terceira falta seguida.</li><li>Acione o Conselho Tutelar nos casos previstos em lei.</li><li>Volte em um mês para conferir.</li></ol><p><b>Resultado esperado.</b> A escola identifica a causa principal das faltas e a frequência começa a subir.</p></div>"},{"id":"c9","titulo":"As regras que organizam a educação municipal","html":"<p>A gestão escolar pública segue um conjunto de normas. Conhecê-las dá segurança às decisões e ajuda a explicar às escolas e às famílias por que as coisas são feitas de determinado modo.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Norma</th><th>O que estabelece</th><th>O que significa na prática</th></tr></thead><tbody><tr><td>Constituição Federal (arts. 205 a 214)</td><td>Educação como direito de todos e dever do Estado e da família. Gestão democrática do ensino público. Prioridade do Município na educação infantil e no ensino fundamental.</td><td>A rede municipal responde pelas vagas e pela qualidade dessas etapas.</td></tr><tr><td>Lei de Diretrizes e Bases (Lei 9.394/1996)</td><td>Art. 11: incumbências do Município. Art. 12: incumbências da escola. Art. 13: dos docentes. Art. 14: gestão democrática. Art. 24: 200 dias e 800 horas, frequência mínima de 75%.</td><td>Define o que cabe à Secretaria, à escola e ao professor.</td></tr><tr><td>Base Nacional Comum Curricular</td><td>Aprendizagens essenciais de cada ano.</td><td>Orienta o currículo da rede e os planos de ensino.</td></tr><tr><td>Plano Nacional e Plano Municipal de Educação</td><td>Metas e estratégias para dez anos.</td><td>O planejamento anual da Secretaria decorre do plano municipal.</td></tr><tr><td>Lei do Fundeb (Lei 14.113/2020)</td><td>Financiamento da educação básica e conselho de acompanhamento.</td><td>Regras de aplicação dos recursos e de prestação de contas.</td></tr><tr><td>Lei 11.947/2009</td><td>Alimentação escolar e Programa Dinheiro Direto na Escola.</td><td>Regras da merenda e dos recursos que chegam à escola.</td></tr><tr><td>Lei 14.644/2023</td><td>Conselhos escolares e fóruns dos conselhos.</td><td>Reforça a participação da comunidade na gestão.</td></tr><tr><td>Estatuto da Criança e do Adolescente</td><td>Direito à educação, ao respeito e à proteção.</td><td>Deveres de comunicação ao Conselho Tutelar.</td></tr><tr><td>Lei Geral de Proteção de Dados (Lei 13.709/2018)</td><td>Tratamento de dados pessoais, com regra própria para crianças e adolescentes.</td><td>Cuidados com cadastros, documentos e sistemas.</td></tr></tbody></table></div><div class=\"tb\"><table><thead><tr><th>Cabe à Secretaria</th><th>Cabe à escola</th><th>Cabe ao professor</th></tr></thead><tbody><tr><td>Organizar a rede, definir normas, prover pessoal e recursos, formar as equipes, acompanhar os resultados.</td><td>Elaborar e executar a proposta pedagógica, administrar pessoal e recursos, cumprir os dias letivos, cuidar da recuperação, articular-se com as famílias, informar a frequência.</td><td>Participar da proposta pedagógica, cumprir o plano de trabalho, zelar pela aprendizagem, propor recuperação, cumprir os dias e as horas, colaborar com a relação entre escola e famílias.</td></tr></tbody></table></div><div class=\"nota\"><b>Normas municipais</b><br/>As normas nacionais são completadas pelas leis e resoluções do Município e do Conselho Municipal de Educação: plano de carreira, estatuto do servidor, regimento da rede e calendário. Este guia não as substitui.</div>"},{"id":"c10","titulo":"Quem é quem na rede","html":"<p>Uma rede funciona quando cada parte sabe o que decide, o que executa e a quem recorre. A falta de clareza gera duas falhas comuns: a escola que espera a Secretaria para tudo, e a Secretaria que faz o trabalho da escola.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Instância</th><th>Papel</th><th>Decide sobre</th></tr></thead><tbody><tr><td>Secretário e equipe dirigente</td><td>Dirigir a política educacional do Município.</td><td>Prioridades, orçamento, normas e pessoal.</td></tr><tr><td>Setor pedagógico</td><td>Currículo, formação, avaliação e acompanhamento da aprendizagem.</td><td>Orientações curriculares, calendário de formação e de avaliações.</td></tr><tr><td>Setor administrativo</td><td>Pessoal, matrícula, alimentação, transporte, patrimônio e compras.</td><td>Lotação, contratos e logística.</td></tr><tr><td>Supervisão ou acompanhamento escolar</td><td>Ligar a Secretaria às escolas.</td><td>Plano de visitas e apoio a cada escola.</td></tr><tr><td>Direção escolar</td><td>Responder pela escola.</td><td>Organização interna, plano de ação, uso dos recursos da escola.</td></tr><tr><td>Coordenação pedagógica</td><td>Cuidar do ensino e da formação dos professores.</td><td>Pauta pedagógica da escola.</td></tr><tr><td>Secretaria escolar</td><td>Cuidar da vida escolar dos alunos.</td><td>Rotinas de registro e de documentos.</td></tr><tr><td>Conselho escolar</td><td>Participar das decisões e acompanhar a gestão.</td><td>Aprova o plano e a aplicação dos recursos da escola.</td></tr></tbody></table></div><h3>Os conselhos de controle social</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Conselho</th><th>O que acompanha</th></tr></thead><tbody><tr><td>Conselho Municipal de Educação</td><td>Normas do sistema municipal, autorização de escolas, calendário e regimentos.</td></tr><tr><td>Conselho de Alimentação Escolar</td><td>A execução do programa de alimentação: cardápios, qualidade e prestação de contas.</td></tr><tr><td>Conselho de Acompanhamento e Controle Social do Fundeb</td><td>A aplicação dos recursos do fundo e o transporte escolar.</td></tr><tr><td>Conselho Tutelar</td><td>A garantia dos direitos de crianças e adolescentes.</td></tr></tbody></table></div><div class=\"nota\"><b>Conselhos são parceiros</b><br/>Conselhos bem informados ajudam a gestão. Reuniões regulares, documentos entregues no prazo e portas abertas evitam a maior parte dos conflitos.</div>"},{"id":"c11","titulo":"O planejamento da rede","html":"<p>O planejamento da Secretaria desce em cascata: das metas de dez anos ao que cada escola fará no bimestre. Cada nível responde a uma pergunta diferente.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Plano Municipal de Educação</b><small>dez anos: aonde a rede quer chegar</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Plano plurianual e orçamento</b><small>quatro anos e um ano: com que recursos</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Plano anual da Secretaria</b><small>um ano: prioridades e ações</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Plano de ação da escola</b><small>um ano: o que cada escola fará</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Plano de ensino</b><small>bimestre: o que cada turma aprenderá</small></div></div><figcaption>Figura. Do plano de dez anos à sala de aula.</figcaption></figure><h3>O plano anual da Secretaria em uma página</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>Conteúdo</th><th>Exemplo</th></tr></thead><tbody><tr><td>Diagnóstico</td><td>Três ou quatro dados que resumem a situação da rede.</td><td>Um terço dos alunos do 5º ano não lê com fluência.</td></tr><tr><td>Prioridades</td><td>No máximo três.</td><td>Alfabetização, recuperação de aprendizagens, frequência.</td></tr><tr><td>Metas</td><td>Uma por prioridade, com número e prazo.</td><td>Reduzir pela metade os alunos abaixo do básico em leitura até dezembro.</td></tr><tr><td>Ações</td><td>O que será feito, por quem e quando.</td><td>Reforço escolar em todas as turmas do 3º ao 9º ano. Formação bimestral.</td></tr><tr><td>Recursos</td><td>De onde vêm.</td><td>Fonte orçamentária e programas federais.</td></tr><tr><td>Acompanhamento</td><td>Como e quando se verifica.</td><td>Reunião mensal de indicadores com os diretores.</td></tr></tbody></table></div><h3>O calendário escolar</h3><ul><li>Garante no mínimo 200 dias de efetivo trabalho escolar e 800 horas.</li><li>Reserva as datas de planejamento, formação, conselhos de classe e reuniões com os responsáveis.</li><li>Prevê as avaliações da rede e as nacionais.</li><li>Indica como serão repostos os dias sem aula.</li><li>É aprovado conforme as normas do sistema municipal e divulgado às famílias antes do início das aulas.</li></ul><div class=\"nota alerta\"><b>Poucas prioridades</b><br/>Uma rede com dez prioridades não tem nenhuma. As escolas só conseguem se dedicar de verdade a duas ou três frentes por ano.</div>"},{"id":"c12","titulo":"Matrícula, turmas e Censo Escolar","html":"<p>A matrícula define quantos alunos, turmas, professores, salas, refeições e vagas de transporte a rede terá. Erros nessa etapa aparecem o ano inteiro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que fazer</th><th>Cuidados</th></tr></thead><tbody><tr><td>Levantamento da demanda</td><td>Estimar alunos por escola e por ano, com base nas matrículas atuais e nos nascimentos e mudanças.</td><td>Atenção às regiões que crescem.</td></tr><tr><td>Rematrícula</td><td>Confirmar os alunos da rede.</td><td>Atualizar endereço, telefones e responsáveis.</td></tr><tr><td>Matrícula nova</td><td>Atender os novos alunos em período divulgado com antecedência.</td><td>Nenhuma criança fica sem vaga por falta de documento. A documentação é regularizada depois.</td></tr><tr><td>Formação das turmas</td><td>Distribuir os alunos conforme os limites definidos pela rede.</td><td>Equilibrar as turmas. Não formar turmas \"fortes\" e \"fracas\".</td></tr><tr><td>Lotação</td><td>Definir professores e demais servidores de cada escola.</td><td>Concluir antes do primeiro dia de aula.</td></tr><tr><td>Ajustes</td><td>Transferências e matrículas ao longo do ano.</td><td>Registrar no mesmo dia.</td></tr></tbody></table></div><h3>Censo Escolar</h3><p>O Censo Escolar é o levantamento anual de dados da educação básica, coordenado pelo Inep. A data de referência é a última quarta-feira de maio. As informações declaradas servem de base para a distribuição de recursos do Fundeb, da alimentação, do transporte, do livro didático e do dinheiro direto na escola.</p><ul class=\"chk\"><li><span></span>Todos os alunos que frequentam estão matriculados no sistema, na turma correta.</li><li><span></span>Alunos que deixaram a escola foram registrados como transferidos ou desligados.</li><li><span></span>Dados de deficiência, transtorno e altas habilidades estão informados conforme a documentação e as orientações do Censo.</li><li><span></span>O uso de transporte escolar está informado.</li><li><span></span>A formação e a função de cada profissional estão atualizadas.</li><li><span></span>A infraestrutura da escola foi conferida.</li><li><span></span>A direção revisou e assinou os dados antes do fechamento.</li></ul><div class=\"nota alerta\"><b>Dado errado custa caro</b><br/>Aluno não informado é recurso que a rede deixa de receber no ano seguinte. Aluno informado sem frequentar é irregularidade. A conferência do Censo é responsabilidade da direção, com apoio da Secretaria.</div>"},{"id":"c13","titulo":"O projeto político-pedagógico","html":"<p>O projeto político-pedagógico diz quem a escola é, o que pretende e como vai trabalhar. A Lei de Diretrizes e Bases atribui à escola a tarefa de elaborá-lo, com a participação dos professores e da comunidade.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>Pergunta que responde</th></tr></thead><tbody><tr><td>Identidade</td><td>Quem somos? Onde estamos? Quem são os nossos alunos e famílias?</td></tr><tr><td>Diagnóstico</td><td>Como estão a aprendizagem, a frequência e a convivência?</td></tr><tr><td>Princípios</td><td>Em que acreditamos sobre ensinar e aprender?</td></tr><tr><td>Objetivos e metas</td><td>O que queremos alcançar nos próximos anos?</td></tr><tr><td>Organização do ensino</td><td>Como ensinamos, avaliamos e recuperamos as aprendizagens?</td></tr><tr><td>Inclusão e convivência</td><td>Como garantimos que todos participem e sejam respeitados?</td></tr><tr><td>Gestão e participação</td><td>Como decidimos? Como as famílias e os alunos participam?</td></tr><tr><td>Formação</td><td>Como a equipe estuda e melhora?</td></tr><tr><td>Acompanhamento</td><td>Como saberemos se estamos avançando?</td></tr></tbody></table></div><h3>Como rever o projeto</h3><ol class=\"passos\"><li>Forme um grupo com direção, coordenação, professores, funcionários, responsáveis e, quando possível, alunos.</li><li>Reúna os dados dos últimos anos.</li><li>Ouça a comunidade com perguntas simples: o que a escola faz bem? O que precisa mudar?</li><li>Reveja as prioridades à luz dos dados e da escuta.</li><li>Escreva de forma curta e clara.</li><li>Apresente ao conselho escolar e à comunidade.</li><li>Transforme as prioridades no plano de ação do ano.</li></ol><h3>O apoio da Secretaria</h3><ul><li>Oferecer um roteiro comum, que deixe espaço para a identidade de cada escola.</li><li>Entregar a cada escola os seus dados organizados.</li><li>Acompanhar a elaboração, sem escrever no lugar da escola.</li><li>Ler os projetos e dar retorno.</li><li>Usar o projeto como referência nas visitas.</li></ul><div class=\"nota\"><b>Regimento escolar</b><br/>O regimento define as regras de funcionamento: direitos e deveres, avaliação, frequência e medidas disciplinares. Muitas redes adotam um regimento comum. As medidas disciplinares nunca podem impedir o acesso do aluno à educação nem expô-lo a constrangimento.</div>"},{"id":"c14","titulo":"O plano de ação da escola","html":"<p>O plano de ação traduz o projeto pedagógico no que será feito neste ano. Um bom plano cabe em uma página e é consultado toda semana.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Prioridade</th><th>Meta</th><th>Ação</th><th>Responsável</th><th>Prazo</th><th>Como verificar</th></tr></thead><tbody><tr><td>Leitura no 3º ano</td><td>Todos os alunos lendo com fluência até novembro.</td><td>Reforço diário de vinte minutos e agrupamento por nível.</td><td>Coordenação e professores do 3º ano</td><td>Março a novembro</td><td>Avaliação de fluência a cada bimestre.</td></tr><tr><td>Frequência</td><td>Nenhuma turma abaixo de 90%.</td><td>Busca ativa na terceira falta.</td><td>Secretaria escolar e direção</td><td>Ano todo</td><td>Relatório semanal de frequência.</td></tr><tr><td>Uso do reforço escolar</td><td>Oito em cada dez alunos praticando toda semana.</td><td>Horário fixo por turma e reunião com os responsáveis.</td><td>Direção</td><td>A partir de março</td><td>Indicador de prática na plataforma.</td></tr></tbody></table></div><h3>Características de uma boa meta</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Característica</th><th>Meta fraca</th><th>Meta forte</th></tr></thead><tbody><tr><td>Específica</td><td>\"Melhorar a leitura.\"</td><td>\"Todos os alunos do 3º ano lendo textos curtos com fluência.\"</td></tr><tr><td>Com número</td><td>\"Reduzir as faltas.\"</td><td>\"Frequência de 90% em todas as turmas.\"</td></tr><tr><td>Com prazo</td><td>\"Assim que possível.\"</td><td>\"Até o fim do segundo bimestre.\"</td></tr><tr><td>Ao alcance da escola</td><td>\"Acabar com a pobreza do bairro.\"</td><td>\"Garantir que todo aluno faltoso seja procurado em três dias.\"</td></tr></tbody></table></div><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Planejar</b><small>Definir metas e ações com a equipe.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Fazer</b><small>Executar o combinado.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Verificar</b><small>Olhar os indicadores todo mês.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Ajustar</b><small>Manter o que funciona e mudar o que não funciona.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O plano é revisto ao longo do ano.</figcaption></figure><div class=\"pratica\"><div class=\"tt\">Para praticar · uma meta da sua área</div><div class=\"q\"><b>1.</b> Escreva uma meta para este ano, com número e prazo.<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Que ação depende só da sua equipe?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Em que data você vai verificar o resultado pela primeira vez?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c15","titulo":"A secretaria escolar e a vida do aluno","html":"<p>A secretaria escolar guarda a história escolar de cada aluno. Um documento errado ou perdido pode atrasar uma matrícula, uma transferência ou a conclusão de uma etapa anos depois.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Documento</th><th>Para que serve</th><th>Cuidados</th></tr></thead><tbody><tr><td>Ficha de matrícula</td><td>Registra os dados do aluno e dos responsáveis.</td><td>Atualizar todo ano. Conferir quem pode retirar o aluno.</td></tr><tr><td>Diário de classe</td><td>Registra frequência, conteúdos e avaliações.</td><td>Preenchimento em dia pelo professor. É documento oficial.</td></tr><tr><td>Ata de resultados finais</td><td>Registra a situação de cada aluno ao fim do ano.</td><td>Conferir com os diários antes de assinar.</td></tr><tr><td>Histórico escolar</td><td>Comprova os estudos realizados.</td><td>Emitir com base nas atas. Sem rasuras.</td></tr><tr><td>Declarações</td><td>Comprovam matrícula, frequência e conclusão.</td><td>Emitir no prazo definido pela rede.</td></tr><tr><td>Transferência</td><td>Permite a continuidade em outra escola.</td><td>Não pode ser negada nem retida por qualquer pendência.</td></tr><tr><td>Pasta individual</td><td>Reúne os documentos do aluno.</td><td>Guarda em local com acesso restrito.</td></tr><tr><td>Laudos e relatórios</td><td>Orientam o atendimento do aluno.</td><td>Dados sensíveis: acesso apenas a quem precisa.</td></tr></tbody></table></div><h3>Rotinas da secretaria escolar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Frequência</th><th>Rotina</th></tr></thead><tbody><tr><td>Todo dia</td><td>Atendimento ao público. Registro de matrículas e transferências. Conferência das faltas e aviso à direção.</td></tr><tr><td>Toda semana</td><td>Relatório de frequência. Atualização do sistema. Arquivo dos documentos recebidos.</td></tr><tr><td>Todo mês</td><td>Envio de informações à Secretaria. Frequência dos beneficiários de programas sociais, conforme o calendário.</td></tr><tr><td>Todo bimestre</td><td>Recebimento e conferência dos diários. Boletins.</td></tr><tr><td>Todo ano</td><td>Matrícula, Censo Escolar, atas finais, históricos e organização do arquivo.</td></tr></tbody></table></div><h3>Atendimento ao público</h3><ul><li>Informar com clareza os documentos e os prazos.</li><li>Atender por ordem, com prioridade legal para idosos, gestantes e pessoas com deficiência.</li><li>Não exigir documento que a escola já possui.</li><li>Nunca condicionar matrícula ou documento a pagamento, doação ou compra.</li><li>Tratar com discrição os assuntos de cada família.</li></ul><div class=\"nota\"><b>Frequência e programas sociais</b><br/>A permanência das famílias em programas de transferência de renda depende da frequência escolar informada. O registro correto e no prazo protege o direito das famílias.</div>"},{"id":"c16","titulo":"Os recursos da escola","html":"<p>Além do que a Secretaria fornece, as escolas recebem recursos de programas federais e gerem bens públicos. Conhecer cada fonte evita perder dinheiro por falta de execução e evita erros na prestação de contas.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Programa</th><th>O que financia</th><th>Quem executa</th><th>Atenção</th></tr></thead><tbody><tr><td>Programa Dinheiro Direto na Escola</td><td>Pequenos reparos, material de consumo, material pedagógico e bens permanentes.</td><td>A unidade executora da escola: conselho escolar, caixa escolar ou associação.</td><td>Plano de aplicação aprovado pela comunidade. Pesquisa de preços. Notas fiscais em nome da unidade executora.</td></tr><tr><td>Programa Nacional de Alimentação Escolar</td><td>Gêneros alimentícios para a merenda.</td><td>O Município, com acompanhamento do conselho de alimentação.</td><td>No mínimo 30% dos recursos federais na compra da agricultura familiar. Cardápio elaborado por nutricionista.</td></tr><tr><td>Programa de apoio ao transporte escolar</td><td>Custeio do transporte de alunos, sobretudo da área rural.</td><td>O Município.</td><td>Veículos e condutores dentro das exigências do Código de Trânsito.</td></tr><tr><td>Programa Nacional do Livro e do Material Didático</td><td>Livros didáticos e literários.</td><td>Escolha pelos professores. Distribuição nacional.</td><td>Registrar a escolha no prazo. Controlar entrega e devolução.</td></tr><tr><td>Fundeb</td><td>Remuneração dos profissionais e manutenção do ensino.</td><td>O Município.</td><td>Proporção mínima para remuneração dos profissionais da educação, definida em lei.</td></tr></tbody></table></div><h3>Regras de ouro do dinheiro público na escola</h3><ul class=\"chk\"><li><span></span>O gasto está previsto no plano aprovado pelo conselho escolar.</li><li><span></span>Houve pesquisa de preços com pelo menos três fornecedores.</li><li><span></span>A nota fiscal está em nome da unidade executora e descreve o que foi comprado.</li><li><span></span>O pagamento foi feito pelos meios permitidos, com identificação do fornecedor.</li><li><span></span>O bem permanente foi registrado no patrimônio.</li><li><span></span>A comunidade foi informada do que entrou e do que foi gasto.</li><li><span></span>A prestação de contas foi entregue no prazo.</li><li><span></span>Os documentos estão guardados pelo tempo exigido.</li></ul><div class=\"nota alerta\"><b>O que não se faz</b><br/>Não se compra de empresa de servidor ou de parente de quem decide. Não se paga em dinheiro vivo fora das regras. Não se divide a compra para fugir de exigências. Não se usa o recurso para finalidade diferente da prevista.</div>"},{"id":"c17","titulo":"Alimentação e transporte","html":"<h3>Alimentação escolar</h3><p>A alimentação escolar é um direito de todos os alunos da educação básica pública. Para muitos, é a principal refeição do dia. Falha na merenda afeta a frequência e a aprendizagem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Etapa</th><th>O que garantir</th><th>Quem</th></tr></thead><tbody><tr><td>Cardápio</td><td>Elaborado por nutricionista, com alimentos variados e adequados à idade e à cultura local.</td><td>Secretaria</td></tr><tr><td>Necessidades especiais</td><td>Cardápio adaptado para alunos com alergias, intolerâncias, diabetes e outras condições, mediante documento de saúde.</td><td>Nutricionista e escola</td></tr><tr><td>Recebimento</td><td>Conferir quantidade, validade e qualidade na entrega.</td><td>Responsável designado na escola</td></tr><tr><td>Armazenamento</td><td>Local limpo, arejado, protegido de pragas. O que vence primeiro é usado primeiro.</td><td>Merendeiras</td></tr><tr><td>Preparo</td><td>Higiene pessoal e do ambiente, uniforme, touca, mãos lavadas.</td><td>Merendeiras</td></tr><tr><td>Distribuição</td><td>Horário respeitado, porção adequada, ambiente tranquilo, sem distinção entre alunos.</td><td>Escola</td></tr><tr><td>Controle</td><td>Registro diário do que foi servido e do estoque.</td><td>Escola</td></tr></tbody></table></div><ul><li>A merenda não é usada como prêmio nem retirada como castigo.</li><li>Sobras e alimentos não são levados para casa por servidores.</li><li>Problemas na entrega são comunicados à Secretaria no mesmo dia.</li><li>O conselho de alimentação escolar tem acesso à cozinha e aos registros.</li></ul><h3>Transporte escolar</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Item</th><th>O que verificar</th></tr></thead><tbody><tr><td>Veículo</td><td>Vistoria em dia, cintos para todos, identificação de escolar, extintor, equipamentos obrigatórios.</td></tr><tr><td>Condutor</td><td>Habilitação na categoria exigida, curso específico e exigências do Código de Trânsito.</td></tr><tr><td>Monitor</td><td>Presença de monitor para apoiar os alunos, sobretudo os menores e os com deficiência.</td></tr><tr><td>Rotas</td><td>Pontos de embarque seguros, tempo de viagem razoável, lista de alunos por rota.</td></tr><tr><td>Embarque e desembarque</td><td>Dentro da área da escola ou em local protegido, com adulto acompanhando.</td></tr><tr><td>Comunicação</td><td>Telefone do condutor com a escola. Aviso imediato de atraso ou ocorrência.</td></tr><tr><td>Acessibilidade</td><td>Veículo adaptado quando há aluno que necessita.</td></tr></tbody></table></div><div class=\"nota\"><b>Frequência e transporte</b><br/>Faltas concentradas em uma rota indicam problema no transporte. A escola avisa a Secretaria antes de cobrar as famílias.</div>"},{"id":"c18","titulo":"Prédio, patrimônio e segurança","html":"<p>O prédio também educa. Uma escola limpa, conservada e segura comunica respeito a quem estuda e trabalha nela.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Área</th><th>O que verificar</th><th>Frequência</th></tr></thead><tbody><tr><td>Água</td><td>Abastecimento, limpeza de caixas e bebedouros, qualidade.</td><td>Diária e semestral</td></tr><tr><td>Banheiros</td><td>Limpeza, funcionamento, papel, sabão, portas e trincos.</td><td>Várias vezes ao dia</td></tr><tr><td>Cozinha e depósito</td><td>Higiene, gás, validade dos alimentos, controle de pragas.</td><td>Diária</td></tr><tr><td>Instalações elétricas</td><td>Fios expostos, quadros, tomadas, iluminação.</td><td>Mensal</td></tr><tr><td>Prevenção de incêndio</td><td>Extintores na validade, saídas desobstruídas, regularidade junto ao Corpo de Bombeiros.</td><td>Mensal e anual</td></tr><tr><td>Telhado, muros e pisos</td><td>Infiltrações, rachaduras, buracos, risco de queda.</td><td>Antes e depois do período de chuvas</td></tr><tr><td>Pátio e quadra</td><td>Brinquedos, traves, alambrados e pisos em condição segura.</td><td>Semanal</td></tr><tr><td>Acessibilidade</td><td>Rampas, corrimãos, banheiro acessível, circulação livre.</td><td>Semestral</td></tr><tr><td>Portaria</td><td>Controle de entrada e saída, identificação de visitantes.</td><td>Diária</td></tr></tbody></table></div><h3>Patrimônio</h3><ul><li>Todo bem permanente tem número e está em uma lista com a localização.</li><li>A direção confere o inventário ao assumir e ao deixar o cargo.</li><li>Equipamentos emprestados a servidores ou alunos têm termo de responsabilidade.</li><li>Tablets e computadores têm controle de entrega, devolução e manutenção.</li><li>Perda, furto ou dano é comunicado à Secretaria e registrado.</li><li>Bens sem uso são devolvidos, e não descartados por conta própria.</li></ul><h3>Como pedir manutenção</h3><ol class=\"passos\"><li>Descreva o problema, o local e o risco.</li><li>Anexe uma foto do local, sem pessoas.</li><li>Classifique: urgente, quando há risco à segurança ou à aula, ou programável.</li><li>Envie pelo canal definido pela Secretaria.</li><li>Isole a área de risco até o reparo.</li><li>Acompanhe o pedido e registre a conclusão.</li></ol><div class=\"nota alerta\"><b>Risco à segurança não espera</b><br/>Fio exposto, vazamento de gás, risco de desabamento e falta de água são comunicados no mesmo momento, e a área é interditada pela direção.</div>"},{"id":"c19","titulo":"Pessoas: lotação, ausências e desenvolvimento","html":"<p>Nenhum recurso pesa tanto na aprendizagem quanto ter, em cada sala, todos os dias, um professor preparado. Organizar as pessoas é a tarefa administrativa de maior efeito pedagógico.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tema</th><th>Boas práticas</th></tr></thead><tbody><tr><td>Lotação</td><td>Concluída antes do início das aulas. Critérios públicos. Atenção especial às escolas mais vulneráveis e aos anos de alfabetização.</td></tr><tr><td>Ausências previstas</td><td>Licenças e afastamentos conhecidos têm substituição planejada.</td></tr><tr><td>Ausências imprevistas</td><td>Cada escola tem um plano: quem assume a turma e que atividades ficam prontas.</td></tr><tr><td>Acolhimento</td><td>Todo servidor novo recebe orientação, material e um colega de referência.</td></tr><tr><td>Formação</td><td>Calendário anual, ligado às prioridades da rede, dentro da jornada.</td></tr><tr><td>Avaliação de desempenho</td><td>Conforme o plano de carreira. Baseada em fatos, com devolutiva e plano de melhoria.</td></tr><tr><td>Período de experiência do servidor</td><td>Acompanhado de perto, com registros e apoio, conforme as normas do Município.</td></tr><tr><td>Saúde do servidor</td><td>Atenção ao adoecimento, à voz e à saúde mental. Encaminhamento ao serviço competente.</td></tr><tr><td>Reconhecimento</td><td>Boas práticas divulgadas na rede. Agradecimento feito de forma específica.</td></tr></tbody></table></div><figure><div class=\"barras\"><div class=\"ln\"><span class=\"rt\">Escola A</span><span class=\"tr\"><span class=\"br\" style=\"width:96%;background:#1E8E5A\"></span></span><span class=\"vl\">96%</span></div><div class=\"ln\"><span class=\"rt\">Escola B</span><span class=\"tr\"><span class=\"br\" style=\"width:91%;background:#1E8E5A\"></span></span><span class=\"vl\">91%</span></div><div class=\"ln\"><span class=\"rt\">Escola C</span><span class=\"tr\"><span class=\"br\" style=\"width:84%;background:#D9920B\"></span></span><span class=\"vl\">84%</span></div><div class=\"ln\"><span class=\"rt\">Escola D</span><span class=\"tr\"><span class=\"br\" style=\"width:77%;background:#C44536\"></span></span><span class=\"vl\">77%</span></div></div><figcaption>Gráfico (exemplo fictício). Aulas dadas em relação às aulas previstas no mês, por escola.</figcaption></figure><h3>Aula prevista é aula dada</h3><ul><li>A Secretaria acompanha, por escola, a proporção de aulas previstas que foram dadas.</li><li>Turma sem professor é comunicada no mesmo dia.</li><li>A escola mantém um banco de atividades por ano e por componente para as substituições.</li><li>O reforço escolar pode ocupar parte de uma aula sem professor, com um adulto acompanhando a turma.</li><li>Ausências frequentes são tratadas em conversa individual, antes de qualquer medida.</li></ul><div class=\"nota\"><b>Conversa antes do registro</b><br/>Diante de atrasos e faltas de um servidor, a primeira medida é perguntar o que está acontecendo. Muitas situações se resolvem com um ajuste de horário ou um encaminhamento de saúde.</div>"},{"id":"c20","titulo":"Avaliações e indicadores da rede","html":"<p>Os indicadores mostram onde a rede está e para onde vai. Nenhum deles, sozinho, explica uma escola. Juntos, orientam onde pôr esforço.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Indicador</th><th>O que mede</th><th>Fonte</th><th>Como usar</th></tr></thead><tbody><tr><td>Frequência</td><td>Presença dos alunos.</td><td>Diário de classe.</td><td>Semanalmente, por turma.</td></tr><tr><td>Aprovação, reprovação e abandono</td><td>O fluxo dos alunos.</td><td>Atas finais e Censo Escolar.</td><td>Anualmente, por ano e por escola.</td></tr><tr><td>Distorção idade-série</td><td>Alunos com dois anos ou mais de atraso.</td><td>Censo Escolar.</td><td>Para planejar a recuperação da trajetória.</td></tr><tr><td>Saeb</td><td>Desempenho em Língua Portuguesa e Matemática em anos selecionados.</td><td>Avaliação nacional, a cada dois anos.</td><td>Para ver a tendência e os níveis de proficiência.</td></tr><tr><td>Ideb</td><td>Combina o desempenho no Saeb com a aprovação.</td><td>Inep.</td><td>Para acompanhar a evolução. Não serve para comparar escolas de contextos muito diferentes.</td></tr><tr><td>Avaliações da rede</td><td>Aprendizagem ao longo do ano.</td><td>Secretaria.</td><td>Para ajustar o ensino a cada bimestre.</td></tr><tr><td>Diagnóstico e prática no reforço</td><td>Habilidades dominadas e uso semanal.</td><td>Plataforma de reforço escolar.</td><td>Para agir toda semana, por turma e por aluno.</td></tr></tbody></table></div><h3>Como ler um resultado</h3><ol class=\"passos\"><li>Olhe a tendência de vários anos, e não um ano isolado.</li><li>Compare a escola com ela mesma.</li><li>Olhe a distribuição: quantos alunos estão em cada nível, e não só a média.</li><li>Verifique quantos alunos participaram. Média alta com pouca participação engana.</li><li>Leia junto os dados de aprendizagem e de fluxo: aprovar sem aprender e aprender reprovando muitos são dois problemas.</li><li>Pergunte o que a escola fez, antes de concluir.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Uso que ajuda</th><th>Uso que prejudica</th></tr></thead><tbody><tr><td>Identificar as escolas que precisam de mais apoio.</td><td>Fazer ranking público de escolas.</td></tr><tr><td>Escolher as prioridades de formação.</td><td>Punir diretores e professores.</td></tr><tr><td>Planejar a recuperação das aprendizagens.</td><td>Treinar os alunos só para a prova.</td></tr><tr><td>Prestar contas à comunidade com clareza.</td><td>Excluir alunos com dificuldade no dia da avaliação.</td></tr></tbody></table></div>"},{"id":"c21","titulo":"Apoio diferenciado às escolas","html":"<p>Tratar todas as escolas do mesmo modo parece justo, mas mantém as diferenças. Escolas com mais dificuldade precisam de mais presença da Secretaria.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação da escola</th><th>Tipo de apoio</th><th>Frequência de acompanhamento</th></tr></thead><tbody><tr><td>Bons resultados e boa organização</td><td>Autonomia, reconhecimento e convite para compartilhar práticas.</td><td>Bimestral</td></tr><tr><td>Resultados medianos</td><td>Apoio no plano de ação e na formação.</td><td>Mensal</td></tr><tr><td>Resultados baixos ou em queda</td><td>Presença próxima, apoio pedagógico e administrativo, prioridade em pessoal e recursos.</td><td>Quinzenal</td></tr><tr><td>Em crise</td><td>Intervenção combinada: equipe da Secretaria presente até a normalização.</td><td>Semanal</td></tr></tbody></table></div><h3>A reunião de diretores</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Tempo</th><th>Parte</th><th>Conteúdo</th></tr></thead><tbody><tr><td>10 min</td><td>Abertura</td><td>Encaminhamentos da reunião anterior.</td></tr><tr><td>30 min</td><td>Indicadores</td><td>Um indicador da rede, lido em grupos de escolas.</td></tr><tr><td>30 min</td><td>Prática</td><td>Uma escola apresenta como resolveu um problema.</td></tr><tr><td>20 min</td><td>Trabalho em grupo</td><td>Diretores ajustam os seus planos.</td></tr><tr><td>10 min</td><td>Informes</td><td>Por escrito, com espaço para dúvidas.</td></tr><tr><td>10 min</td><td>Combinados</td><td>O que cada um leva para a escola.</td></tr></tbody></table></div><h3>Reduzir a carga sobre as escolas</h3><ul><li>Um único canal de comunicação da Secretaria com as escolas.</li><li>Um envio semanal, em dia fixo, com tudo o que a escola precisa saber.</li><li>Pedidos com prazo razoável e modelo pronto.</li><li>Nenhum setor pede à escola uma informação que a Secretaria já tem em sistema.</li><li>Convocações de diretores e professores concentradas, fora do horário de aula sempre que possível.</li><li>Revisão anual: que relatório pode deixar de existir?</li></ul><div class=\"nota\"><b>A Secretaria existe para a escola</b><br/>Cada pedido da Secretaria consome tempo que a direção deixa de dedicar à sala de aula. A pergunta a fazer antes de enviar é: isto ajuda a escola a ensinar melhor?</div>"},{"id":"c22","titulo":"Inclusão, frequência e proteção na gestão da rede","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Frente</th><th>O que a Secretaria organiza</th><th>O que acompanha</th></tr></thead><tbody><tr><td>Educação inclusiva</td><td>Salas de recursos, atendimento educacional especializado, profissionais de apoio, transporte acessível, formação.</td><td>Alunos atendidos, planos individuais e tempo de espera por apoio.</td></tr><tr><td>Frequência e busca ativa</td><td>Fluxo de comunicação das faltas, parceria com saúde e assistência, comunicação ao Conselho Tutelar.</td><td>Alunos com faltas acima do limite e retornos obtidos.</td></tr><tr><td>Recuperação das aprendizagens</td><td>Reforço escolar, horários, equipamentos e formação.</td><td>Prática semanal e habilidades recuperadas.</td></tr><tr><td>Proteção</td><td>Protocolo de comunicação de violências, plano de segurança das escolas, formação das equipes.</td><td>Casos comunicados e escolas com plano atualizado.</td></tr><tr><td>Convivência</td><td>Orientações sobre regimento, medidas disciplinares e prevenção ao bullying.</td><td>Ocorrências e medidas adotadas.</td></tr><tr><td>Saúde na escola</td><td>Articulação com a rede de saúde: vacinação, visão, saúde bucal.</td><td>Ações realizadas por escola.</td></tr></tbody></table></div><h3>Trabalho com outras secretarias</h3><p>Muitos problemas que aparecem na escola não se resolvem só com educação. A articulação com saúde, assistência social, segurança e conselhos funciona melhor quando há reuniões regulares, fluxos escritos e pessoas de referência em cada órgão.</p><ul class=\"chk\"><li><span></span>Há um fluxo escrito para comunicar faltas e suspeitas de violência.</li><li><span></span>Cada escola conhece a unidade de saúde e o CRAS de referência.</li><li><span></span>Existe uma reunião periódica da rede de proteção com a participação da educação.</li><li><span></span>Os dados compartilhados entre órgãos são os estritamente necessários.</li><li><span></span>A Secretaria dá retorno às escolas sobre os encaminhamentos, dentro do que o sigilo permite.</li></ul><h3>Proteção de dados na gestão</h3><ul><li>Dados de alunos são usados apenas para finalidades educacionais e de proteção.</li><li>Listas com nomes, endereços e telefones não circulam em aplicativos de mensagens.</li><li>Laudos e relatórios têm acesso restrito.</li><li>Pedidos de dados por terceiros são encaminhados ao encarregado de dados do Município.</li><li>Fotos e vídeos de alunos só são divulgados com autorização dos responsáveis.</li></ul>"},{"id":"c23","titulo":"Imprevistos e continuidade das aulas","html":"<p>Falta de água, queda de energia, chuva forte e greve de transporte interrompem aulas com frequência. Um combinado prévio evita decisões improvisadas e diferentes em cada escola.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Primeira medida</th><th>Quem decide a suspensão</th><th>Depois</th></tr></thead><tbody><tr><td>Falta de água</td><td>Verificar reserva e previsão de retorno.</td><td>Direção com a Secretaria.</td><td>Pedido de carro-pipa ou reparo. Reposição.</td></tr><tr><td>Falta de energia</td><td>Avaliar iluminação, ventilação e segurança.</td><td>Direção com a Secretaria.</td><td>Aulas em espaços iluminados, se possível.</td></tr><tr><td>Chuva forte e alagamento</td><td>Manter os alunos em local seguro. Avaliar o trajeto.</td><td>Secretaria, com a defesa civil.</td><td>Vistoria do prédio antes do retorno.</td></tr><tr><td>Problema estrutural</td><td>Isolar a área.</td><td>Secretaria, com a engenharia.</td><td>Remanejamento de turmas.</td></tr><tr><td>Surto de doença</td><td>Seguir a orientação da vigilância em saúde.</td><td>Secretaria, com a saúde.</td><td>Comunicação às famílias e limpeza.</td></tr><tr><td>Falta de merenda</td><td>Comunicar no mesmo momento.</td><td>Secretaria.</td><td>Reposição do alimento. As aulas não são suspensas sem avaliação.</td></tr><tr><td>Ausência de vários professores</td><td>Reorganizar turmas e horários.</td><td>Direção.</td><td>Comunicar à Secretaria e repor conteúdos.</td></tr></tbody></table></div><h3>O que toda escola deve ter pronto</h3><ul class=\"chk\"><li><span></span>Lista de telefones de emergência e dos setores da Secretaria.</li><li><span></span>Canal oficial de aviso aos responsáveis.</li><li><span></span>Critério combinado para liberar alunos: entrega aos responsáveis.</li><li><span></span>Banco de atividades para dias sem professor.</li><li><span></span>Plano de abandono do prédio e ponto de encontro.</li><li><span></span>Registro de cada interrupção, para a reposição.</li></ul><div class=\"nota\"><b>Cada dia conta</b><br/>Somados, os dias perdidos por imprevistos chegam a semanas no ano. Registrar e repor é uma obrigação legal e uma questão de justiça com os alunos.</div>"},{"id":"c24","titulo":"O ano do gestor, mês a mês","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Período</th><th>Na Secretaria</th><th>Na escola</th></tr></thead><tbody><tr><td>Janeiro</td><td>Lotação, matrícula, calendário, compras, vistoria dos prédios.</td><td>Organização das turmas, salas e horários.</td></tr><tr><td>Fevereiro</td><td>Semana pedagógica da rede. Entrega de materiais.</td><td>Acolhida, combinados, reunião com responsáveis, plano de ação.</td></tr><tr><td>Março</td><td>Diagnóstico inicial. Primeira reunião de diretores com dados.</td><td>Diagnóstico das turmas. Início do reforço. Entrega dos acessos.</td></tr><tr><td>Abril</td><td>Visitas de acompanhamento. Formação.</td><td>Conselho de classe do primeiro bimestre.</td></tr><tr><td>Maio</td><td>Conferência do Censo Escolar.</td><td>Dados do Censo revisados pela direção.</td></tr><tr><td>Junho</td><td>Balanço do semestre. Ajuste do plano.</td><td>Conselho de classe. Reunião com responsáveis.</td></tr><tr><td>Julho</td><td>Manutenção dos prédios no recesso. Planejamento do segundo semestre.</td><td>Recesso e reorganização.</td></tr><tr><td>Agosto</td><td>Formação. Atenção às escolas prioritárias.</td><td>Retomada, busca ativa dos alunos que não voltaram.</td></tr><tr><td>Setembro</td><td>Visitas de acompanhamento.</td><td>Conselho de classe do terceiro bimestre.</td></tr><tr><td>Outubro</td><td>Levantamento da demanda para o ano seguinte. Avaliações externas, nos anos em que ocorrem.</td><td>Preparação sem treino excessivo. Recuperação.</td></tr><tr><td>Novembro</td><td>Planejamento do ano seguinte. Rematrícula.</td><td>Rematrícula. Avaliação do plano de ação.</td></tr><tr><td>Dezembro</td><td>Balanço do ano. Prestação de contas.</td><td>Conselho final, atas, históricos, inventário.</td></tr></tbody></table></div><div class=\"nota\"><b>Adapte ao calendário da rede</b><br/>As datas variam conforme o calendário escolar do Município e os cronogramas dos programas federais. O quadro serve de referência para que nada importante seja lembrado em cima da hora.</div>"},{"id":"c25","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · a escola sem professor de Matemática</div><p><b>Situação.</b> Uma escola está há seis semanas sem professor de Matemática em três turmas do 7º ano.</p><p><b>O que fazer.</b></p><ol><li>A direção comunica a falta à Secretaria no primeiro dia.</li><li>A Secretaria providencia a substituição com prioridade.</li><li>Enquanto isso, a coordenação organiza atividades e o reforço escolar nos horários vagos, com um adulto em sala.</li><li>Na chegada do professor, o mapa da turma mostra o que retomar.</li><li>A Secretaria revê o procedimento de substituição para reduzir o tempo de resposta.</li></ol><p><b>Resultado esperado.</b> As turmas recuperam o conteúdo, e a rede passa a acompanhar as aulas previstas e dadas.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · o recurso que voltou</div><p><b>Situação.</b> Uma escola não executou os recursos do dinheiro direto na escola por dois anos, por receio de errar na prestação de contas.</p><p><b>O que fazer.</b></p><ol><li>A Secretaria oferece orientação prática à direção e ao conselho escolar.</li><li>A escola elabora o plano de aplicação com a comunidade.</li><li>As compras seguem a lista de verificação deste guia.</li><li>A prestação de contas é revisada pela Secretaria antes do envio.</li><li>O que foi comprado é apresentado em reunião de responsáveis.</li></ol><p><b>Resultado esperado.</b> A escola executa os recursos e a comunidade acompanha.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · os números que não fechavam</div><p><b>Situação.</b> Na conferência do Censo, uma escola tem 40 alunos a mais no sistema do que em sala.</p><p><b>O que fazer.</b></p><ol><li>A direção confronta as listas de chamada com o sistema.</li><li>A secretaria escolar identifica alunos transferidos e desistentes não registrados.</li><li>Os alunos sem frequência entram na busca ativa antes de qualquer baixa.</li><li>Os registros são corrigidos dentro do prazo.</li><li>A escola adota a conferência mensal das matrículas.</li></ol><p><b>Resultado esperado.</b> Os dados passam a refletir a realidade, e doze alunos retornam.</p></div>"},{"id":"c26","titulo":"Gestão democrática na prática","html":"<p>A gestão democrática é princípio constitucional do ensino público. Ela se realiza quando a comunidade participa de decisões reais, e não apenas assina atas.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Instância</th><th>Quem participa</th><th>O que decide ou acompanha</th><th>Como fortalecer</th></tr></thead><tbody><tr><td>Conselho escolar</td><td>Direção, professores, funcionários, responsáveis, alunos e comunidade.</td><td>Plano de ação, aplicação dos recursos, regimento, calendário de eventos.</td><td>Eleição divulgada, reuniões em horário possível, pauta enviada antes, linguagem simples.</td></tr><tr><td>Conselho de classe</td><td>Professores, coordenação e direção. Em muitas redes, representantes de alunos.</td><td>Percurso das turmas e encaminhamentos.</td><td>Foco na aprendizagem e escuta prévia dos alunos.</td></tr><tr><td>Grêmio ou representação estudantil</td><td>Alunos eleitos pelos colegas.</td><td>Propostas sobre a vida da escola.</td><td>Professor orientador, espaço de reunião e resposta às propostas.</td></tr><tr><td>Assembleia de turma</td><td>Alunos e professor.</td><td>Combinados e problemas da turma.</td><td>Regularidade e cumprimento do que foi decidido.</td></tr><tr><td>Reunião de responsáveis</td><td>Famílias e equipe.</td><td>Informação, escuta e combinados.</td><td>Horários alternativos e retorno sobre as sugestões.</td></tr><tr><td>Associação de pais e mestres ou caixa escolar</td><td>Responsáveis e servidores.</td><td>Gestão de recursos e apoio à escola.</td><td>Prestação de contas visível.</td></tr></tbody></table></div><h3>Uma reunião de conselho escolar que funciona</h3><ol class=\"passos\"><li>Convocar com uma semana de antecedência, com a pauta.</li><li>Começar pelo que foi decidido na reunião anterior e o que foi feito.</li><li>Apresentar as informações em linguagem simples, com números visíveis.</li><li>Ouvir primeiro os responsáveis e os alunos.</li><li>Decidir por consenso ou por voto, conforme o regimento.</li><li>Registrar em ata curta, lida ao final.</li><li>Divulgar as decisões no mural e nos canais da escola.</li></ol><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Participação de fachada</th><th>Participação de verdade</th></tr></thead><tbody><tr><td>A direção traz tudo decidido.</td><td>O conselho discute alternativas.</td></tr><tr><td>Só se pede assinatura.</td><td>Os documentos são explicados antes.</td></tr><tr><td>Reuniões no horário de trabalho das famílias.</td><td>Horário combinado com os representantes.</td></tr><tr><td>Sugestões sem resposta.</td><td>Cada sugestão recebe retorno, mesmo que seja \"não é possível, por tal motivo\".</td></tr><tr><td>Sempre as mesmas pessoas.</td><td>Convite ativo a famílias que não costumam vir.</td></tr></tbody></table></div><h3>O papel da Secretaria</h3><ul><li>Garantir que toda escola tenha conselho escolar constituído e ativo.</li><li>Formar os conselheiros sobre o papel do conselho e sobre os recursos da escola.</li><li>Promover o encontro dos conselhos da rede.</li><li>Ouvir os conselhos na elaboração do plano anual.</li><li>Acompanhar a regularidade das reuniões e das prestações de contas.</li></ul>"},{"id":"c27","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"O ciclo do ano letivo\"</td><td>O que é, para nós, uma escola bem organizada? Os documentos da escola são consultados?</td></tr><tr><td>2</td><td>De \"Rotinas que não podem falhar\" até \"Família, comunidade e conselho escolar\"</td><td>Que rotina mais falha? Como são as nossas visitas de acompanhamento?</td></tr><tr><td>3</td><td>De \"As regras que organizam a educação municipal\" até \"O plano de ação da escola\"</td><td>As nossas prioridades são poucas e claras? As metas têm número e prazo?</td></tr><tr><td>4</td><td>De \"A secretaria escolar\" até \"Pessoas\"</td><td>Como está a execução dos recursos? Toda aula prevista é dada?</td></tr><tr><td>5</td><td>De \"Avaliações e indicadores\" até o final</td><td>Como apoiamos as escolas com mais dificuldade? O que pedimos às escolas que poderia deixar de ser pedido?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>Anotar em uma página o que o grupo combinou em cada encontro ajuda a ver, ao final, o que mudou na prática da escola.</div>"},{"id":"c28","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> As quatro dimensões da gestão escolar são:</p><ol type=\"a\"><li>Ensino, pesquisa, extensão e gestão.</li><li>Infantil, fundamental, médio e superior.</li><li>Pedagógica, de pessoas, administrativa e de convivência e proteção.</li><li>Financeira, jurídica, política e social.</li></ol></div><div class=\"qz\"><p><b>2.</b> Um bom plano de ação tem:</p><ol type=\"a\"><li>Muitas metas.</li><li>Poucas metas, com ações, prazos e responsáveis, revisto a cada bimestre.</li><li>Apenas o diagnóstico.</li><li>Validade de cinco anos.</li></ol></div><div class=\"qz\"><p><b>3.</b> A visita de acompanhamento deve terminar com:</p><ol type=\"a\"><li>Uma advertência.</li><li>Um relatório de falhas.</li><li>Até três ações combinadas, com prazo e apoio da Secretaria.</li><li>Uma nota para a escola.</li></ol></div><div class=\"qz\"><p><b>4.</b> Os indicadores da rede servem para:</p><ol type=\"a\"><li>Fazer ranking de escolas.</li><li>Decidir onde a Secretaria deve apoiar mais.</li><li>Punir direções.</li><li>Divulgar nomes de alunos.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> c) Pedagógica, de pessoas, administrativa e de convivência e proteção. Todas precisam funcionar juntas.</p><p><b>2.</b> b) Poucas metas, com ações, prazos e responsáveis, revisto a cada bimestre. Plano curto e consultado.</p><p><b>3.</b> c) Até três ações combinadas, com prazo e apoio da Secretaria. A visita serve para apoiar.</p><p><b>4.</b> b) Decidir onde a Secretaria deve apoiar mais. Indicador orienta o apoio.</p></div>"},{"id":"c29","titulo":"Glossário","html":"<dl><dt>Busca ativa</dt><dd>Ação para localizar e trazer de volta o aluno que deixou de frequentar.</dd><dt>Calendário escolar</dt><dd>Organização dos dias letivos, recessos, reuniões e avaliações do ano.</dd><dt>Censo Escolar</dt><dd>Levantamento anual de dados da educação básica, coordenado pelo Inep.</dd><dt>Conselho de classe</dt><dd>Reunião que avalia o percurso das turmas e decide encaminhamentos.</dd><dt>Conselho escolar</dt><dd>Colegiado com representantes da comunidade escolar, que participa da gestão.</dd><dt>Distorção idade-série</dt><dd>Situação do aluno com dois anos ou mais de atraso em relação ao ano esperado.</dd><dt>Fundeb</dt><dd>Fundo que financia a educação básica pública.</dd><dt>Gestão democrática</dt><dd>Princípio de participação da comunidade nas decisões da escola pública.</dd><dt>Ideb</dt><dd>Índice que combina o desempenho dos alunos em avaliação nacional com a taxa de aprovação.</dd><dt>Lotação</dt><dd>Definição da escola e da função de cada servidor.</dd><dt>Plano de ação</dt><dd>Documento com as prioridades, metas e ações da escola para o ano.</dd><dt>Projeto político-pedagógico</dt><dd>Documento que define a identidade, os objetivos e a organização do trabalho da escola.</dd><dt>Regimento escolar</dt><dd>Conjunto de regras de funcionamento da escola.</dd><dt>Saeb</dt><dd>Sistema de Avaliação da Educação Básica, com provas nacionais periódicas.</dd><dt>Unidade executora</dt><dd>Entidade da escola que recebe e administra recursos.</dd></dl>"}];

/** Avaliação final do livro. O gabarito só é usado no servidor. */
export const avaliacao: QuestaoDaAvaliacao[] = [{"pergunta":"A elaboração da proposta pedagógica cabe:","alternativas":["À escola, com participação dos professores e da comunidade.","Ao Ministério da Educação.","Ao conselho tutelar.","Só à Secretaria."],"correta":0,"explicacao":"É incumbência da escola, segundo a LDB."},{"pergunta":"Um bom plano anual da Secretaria tem:","alternativas":["Dez prioridades.","No máximo três prioridades, com metas e prazos.","Apenas o orçamento.","Só o calendário."],"correta":1,"explicacao":"Poucas prioridades permitem foco."},{"pergunta":"Uma criança sem documentos no ato da matrícula:","alternativas":["É matriculada, e a documentação é regularizada depois.","Aguarda o ano seguinte.","É encaminhada a outra cidade.","Fica sem vaga."],"correta":0,"explicacao":"O direito à educação vem primeiro."},{"pergunta":"A data de referência do Censo Escolar é:","alternativas":["A última quarta-feira de maio.","O último dia do ano.","Definida por cada escola.","O primeiro dia de aula."],"correta":0,"explicacao":"Os dados orientam a distribuição de recursos."},{"pergunta":"Com recursos do dinheiro direto na escola, deve-se:","alternativas":["Guardar o dinheiro.","Comprar de parente do diretor.","Seguir o plano aprovado e fazer pesquisa de preços.","Pagar sem nota."],"correta":2,"explicacao":"Plano, pesquisa, nota e prestação de contas."},{"pergunta":"A alimentação escolar:","alternativas":["É direito de todos os alunos e não é usada como prêmio ou punição.","É só para quem paga.","Dispensa nutricionista.","Pode ser retirada como castigo."],"correta":0,"explicacao":"É direito do aluno."},{"pergunta":"Para ler um resultado de avaliação, deve-se:","alternativas":["Comparar com a escola mais rica.","Fazer ranking.","Olhar só a média de um ano.","Olhar a tendência, a distribuição por nível e a participação."],"correta":3,"explicacao":"A média sozinha engana."},{"pergunta":"Escolas com resultados mais baixos devem receber:","alternativas":["Punição.","O mesmo de todas.","Menos atenção.","Mais presença e apoio da Secretaria."],"correta":3,"explicacao":"Apoio diferenciado reduz desigualdades."}];
